(async()=>{var NAME='航班座位号查询';var ID='';var q=function(s){try{return document.querySelectorAll(s).length}catch(e){return -1}};var brief=function(n){var c=String(n.className||'').trim().split(/\s+/).filter(Boolean).slice(0,4).join('.');return n.tagName.toLowerCase()+(c?'.'+c:'')+(n.id?'#'+n.id:'')};var chain=function(el){var o=[],n=el,i=0;while(n&&n.nodeType===1&&i++<8){o.push(brief(n));n=n.parentElement}return o};var info=function(r){return{tag:r.tagName.toLowerCase(),cid:r.getAttribute('data-cid'),cls:String(r.className||'').slice(0,90),type:r.getAttribute('data-interactive-target-type'),layerItem:r.classList.contains('layer-item'),vis:!!(r.getClientRects&&r.getClientRects().length),text:(r.textContent||'').replace(/\s+/g,' ').trim().slice(0,40),chain:chain(r)}};var allRows=function(){return Array.prototype.slice.call(document.querySelectorAll('[data-cid]'))};var byName=function(){return allRows().filter(function(r){return(r.textContent||'').indexOf(NAME)>=0}).map(info)};var tabs=Array.prototype.slice.call(document.querySelectorAll('.md-tab')).map(function(t){return{id:t.getAttribute('data-id'),label:(t.textContent||'').trim(),stale:t.hasAttribute('data-stale')}});var rootEl=document.querySelector('#md-recent-tabs-root');var hit=tabs.filter(function(t){return t.label.indexOf(NAME)>=0})[0];var targetId=ID||(hit?hit.id:null);var inputs=Array.prototype.slice.call(document.querySelectorAll('input')).slice(0,12).map(function(b){var r=b.getBoundingClientRect();return{ph:b.getAttribute('placeholder'),val:b.value,type:b.type,w:Math.round(r.width),top:Math.round(r.top)}});var sb=Array.prototype.slice.call(document.querySelectorAll('input')).filter(function(b){var ph=b.getAttribute('placeholder')||'';if(!/搜索|查找|检索/.test(ph))return false;var r=b.getBoundingClientRect();return r.width>40&&r.top<300})[0]||null;var before=byName();var cidHitTotal=targetId?q('[data-cid="'+targetId+'"]'):null;var afterSearch=null,afterVal=null;if(sb){var d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');var orig=sb.value;d.set.call(sb,NAME);sb.dispatchEvent(new Event('input',{bubbles:true}));sb.dispatchEvent(new Event('change',{bubbles:true}));await new Promise(function(r){setTimeout(r,1200)});afterSearch=byName();afterVal=sb.value;d.set.call(sb,orig);sb.dispatchEvent(new Event('input',{bubbles:true}))}var toggles=Array.prototype.slice.call(document.querySelectorAll('[aria-expanded="false"]')).slice(0,10).map(brief);var proj=(location.pathname.match(/\/proto\/design\/([^\/?#]+)/)||[])[1]||null;var hist=proj?localStorage.getItem('screen-history-onLeave-project-'+proj):null;var out={ts:new Date().toISOString(),url:location.href,projCid:proj,coreVersionAttr:rootEl?rootEl.getAttribute('data-md-version'):null,tabs:tabs,targetId:targetId,cidHitTotal:cidHitTotal,nameRowsBefore:before,searchBoxDetected:!!sb,searchBoxValueAfterTest:afterVal,inputs:inputs,nameRowsAfterSearch:afterSearch,anchors:{canvas:q('#screen-scroll-list,#screen_list,.screen-list-container,#mobile-screen-tree'),pageList:q('#mb-enabled-canvas-list,#canvas-scroll-list,.canvas-scroll-list,.canvas-sortable-list'),layerTree:q('#mb-enabled-layer-list,#layer-scroll-list,.layer-scroll-list,.layer-sortable-list,#mb-state-list')},rowTotal:q('[data-cid]'),ariaExpandedFalse:toggles,screenHistory:hist};var s=JSON.stringify(out,null,1);console.log(s);if(typeof copy==='function')copy(s);return out})()
